const STORAGE_KEY='tiendaDemoModa_v2';const seed={theme:'mediterranea',role:'shopper',page:'tienda',tab:'resumen',category:'',coupon:'',customer:{name:'Cliente Demo',email:'cliente@example.test',phone:'600 000 000',address:'Calle Ejemplo 1',city:'Madrid',postcode:'28001'},profile:{contact:'Tienda Demo',email:'contacto@example.test',phone:'600 000 000'},products:[{id:1,name:'Camiseta esencial (demo)',category:'Mujer',price:19.90,stock:18,type:'shirt',color:'#d7c9b7',sizes:'XS, S, M, L, XL',colors:'Arena, Negro',badge:'Básico'},{id:2,name:'Sudadera urbana (demo)',category:'Hombre',price:49.90,stock:9,type:'sweatshirt',color:'#727a77',sizes:'S, M, L, XL',colors:'Salvia, Gris',badge:'Más vendido'},{id:3,name:'Vestido fluido (demo)',category:'Mujer',price:54.90,oldPrice:69.90,stock:6,type:'dress',color:'#b57962',sizes:'XS, S, M, L',colors:'Terracota, Marfil',badge:'Rebajado'},{id:4,name:'Pantalón recto (demo)',category:'Hombre',price:44.90,stock:12,type:'pants',color:'#606975',sizes:'38, 40, 42, 44, 46',colors:'Azul, Negro',badge:''},{id:5,name:'Jersey ligero (demo)',category:'Mujer',price:39.90,stock:0,type:'sweater',color:'#b7a58d',sizes:'XS, S, M, L',colors:'Piedra, Oliva',badge:'Agotado'},{id:6,name:'Camiseta algodón (demo)',category:'Hombre',price:24.90,stock:14,type:'shirt',color:'#78909a',sizes:'S, M, L, XL',colors:'Azul, Blanco',badge:'Nuevo'},{id:7,name:'Sudadera mini (demo)',category:'Infantil',price:29.90,stock:8,type:'sweatshirt',color:'#c89580',sizes:'4, 6, 8, 10',colors:'Rosa, Arena',badge:''},{id:8,name:'Camiseta infantil (demo)',category:'Infantil',price:16.90,stock:11,type:'shirt',color:'#9b9e72',sizes:'4, 6, 8, 10',colors:'Oliva, Crudo',badge:'Nuevo'}],orders:[{id:'DEMO-129',customer:'Cliente Demo',email:'cliente@example.test',date:'30 oct 2026',total:17.91,status:'En preparación',items:[{name:'Camiseta esencial (demo)',size:'M',color:'Arena',qty:1,price:19.90}]},{id:'DEMO-128',customer:'Andrea Ejemplo',email:'andrea@example.test',date:'28 oct 2026',total:74.80,status:'Pendiente de pago',items:[{name:'Vestido fluido (demo)',size:'S',color:'Terracota',qty:1,price:54.90},{name:'Camiseta esencial (demo)',size:'M',color:'Negro',qty:1,price:19.90}]},{id:'DEMO-127',customer:'Mario Ejemplo',email:'mario@example.test',date:'25 oct 2026',total:49.90,status:'Completado',items:[{name:'Sudadera urbana (demo)',size:'L',color:'Salvia',qty:1,price:49.90}]}],users:[{name:'Administración Demo',email:'admin@example.test',role:'Administrador',since:'01 oct 2026'},{name:'Equipo Demo',email:'equipo@example.test',role:'Empleado',since:'08 oct 2026'},{name:'Cliente Demo',email:'cliente@example.test',role:'Cliente',since:'15 oct 2026'},{name:'Andrea Ejemplo',email:'andrea@example.test',role:'Cliente',since:'20 oct 2026'}],categories:['Mujer','Hombre','Infantil','Novedades'],coupons:[{code:'DEMO10',discount:10,expires:'31 dic 2026',maxUses:100,uses:1,active:true}],cart:[]};const clone=value=>JSON.parse(JSON.stringify(value));let state;try{state={...clone(seed),...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')};}catch{state=clone(seed);}const app=document.querySelector('#app');const roleSelect=document.querySelector('#role-select');const dialog=document.querySelector('#dialog');const money=amount=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(Number(amount)||0);const esc=value=>String(value??'').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const persist = () => localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
const toast = text => { const el = document.querySelector('#toast'); el.textContent = text; el.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2600); };
const cartQty = () => state.cart.reduce((sum, line) => sum + line.qty, 0);
const isManager = () => state.role === 'admin' || state.role === 'employee';

function garment(type, color, extra = '') {
  const paths = {
    shirt: '<path d="M39 28 52 19h16l13 9 15 8-9 17-10-5v43H39V47l-10 5-9-17z"/><path class="garment-detail" d="m49 22 11 12 11-12M60 34v48"/>',
    sweatshirt: '<path d="M39 28 52 19h16l13 9 15 11-10 17-10-6v39H39V51l-10 6-10-17z"/><path class="garment-detail" d="M48 22c0 15 24 15 24 0M45 72h30"/>',
    dress: '<path d="M43 20h34l7 17-8 12 15 40H29l15-40-8-12z"/><path class="garment-detail" d="m46 23 14 13 14-13M40 58h40"/>',
    pants: '<path d="M36 20h48l-4 69H61l-4-39-4 39H31z"/><path class="garment-detail" d="M36 30h46M60 20v30"/>',
    sweater: '<path d="M39 28 52 19h16l13 9 15 12-10 17-10-6v38H39V50l-10 7-10-17z"/><path class="garment-detail" d="M48 22c0 15 24 15 24 0M42 75h36"/>'
  };
  return `<div class="garment ${extra}"><svg viewBox="0 0 120 110" role="img" aria-label="Prenda de muestra" style="--garment:${esc(color||'#b8aa99')}"><ellipse cx="60" cy="99" rx="36" ry="5" fill="#000" opacity=".08"/>${paths[type] || paths.shirt}</svg><span class="garment-caption">TU MARCA / PRENDA DE MUESTRA</span></div>`;
}

function productCard(product) {
  return `<article class="product-card"><a class="product-image" href="#producto/${product.id}">${product.badge ? `<span class="badge ${product.badge==='Agotado'?'badge-muted':''}">${esc(product.badge)}</span>` : ''}${garment(product.type, product.color)}<span class="quick-view">Ver prenda ↗</span></a><div class="product-meta"><div><a href="#producto/${product.id}" class="product-name">${esc(product.name)}</a><span class="product-category">${esc(product.category)} · tallas ${esc(product.sizes)}</span></div><strong>${money(product.price)}</strong></div>${product.oldPrice ? `<div class="old-price">Antes ${money(product.oldPrice)}</div>` : ''}<button class="add-button" data-add="${product.id}" ${product.stock < 1 ? 'disabled' : ''}>${product.stock < 1 ? 'Agotado' : 'Añadir a la bolsa'}</button></article>`;
}

function themeCopy() {
  return {
    editorial: ['Una forma nueva de mirar lo cotidiano.', 'Prendas esenciales, historias que duran.'],
    mediterranea: ['Vestirse también es sentirse en casa.', 'Texturas suaves, tonos que acompañan.'],
    street: ['VISTE A TU MANERA.', 'Piezas para tu ritmo. Sin reglas.'],
    premium: ['Menos ruido. Más intención.', 'Diseño cuidado para todos los días.']
  }[state.theme] || ['Vestirse también es sentirse en casa.', 'Texturas suaves, tonos que acompañan.'];
}

function homePage() {
  const [headline, sub] = themeCopy();
  const cats = state.categories.filter(name => name !== 'Novedades');
  return `<section class="hero hero-${esc(state.theme)}"><div class="hero-copy"><span class="eyebrow">NUEVA TEMPORADA · COLECCIÓN DEMO</span><h1>${esc(headline)}</h1><p>${esc(sub)} Una tienda de moda con productos, tallas y colores de muestra.</p><a class="button-primary" href="#coleccion/novedades">Descubrir novedades <span>↗</span></a><div class="hero-note">[ Tu marca ] <i>·</i> Estilo que se adapta</div></div><div class="hero-visual">${garment('dress', '#b98670', 'hero-garment')}<span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="hero-stamp">VISTE<br>A TU<br>MANERA</span></div><div class="hero-index"><span>01 — 04</span><span>MODA · DEMOSTRACIÓN</span></div></section>
    <section class="category-strip"><div class="section-intro"><span class="eyebrow">ENCUENTRA TU COLECCIÓN</span><h2>Explora por categoría</h2></div><div class="category-links">${cats.map((name, i) => `<a href="#coleccion/${encodeURIComponent(name.toLowerCase())}"><sup>0${i + 1}</sup><span>${esc(name)}</span><b>↗</b></a>`).join('')}<a href="#coleccion/novedades"><sup>04</sup><span>Novedades</span><b>↗</b></a></div></section>
    <section class="product-section"><div class="section-heading"><div><span class="eyebrow">PIEZAS SELECCIONADAS</span><h2>Lo nuevo, para llevar</h2><p>Ocho prendas de ejemplo con tallas, colores, stock y precio editables.</p></div><a class="text-link" href="#coleccion/todas">Ver toda la colección ↗</a></div><div class="product-grid">${state.products.slice(0, 4).map(productCard).join('')}</div></section>
    <section class="feature-band"><div class="feature-copy"><span class="eyebrow">LA TIENDA, A TU RITMO</span><h2>Elige la prenda.<br>El resto es sencillo.</h2><p>Busca, selecciona talla y color, usa tu cupón y completa el pedido de muestra. No se realiza ningún cobro.</p><a href="#coleccion/todas" class="text-link">Ver el catálogo completo ↗</a></div><div class="feature-art">${garment('sweatshirt', '#7d8980')}<span>CALIDAD · COMODIDAD · ESTILO</span></div></section>`;
}

function collectionPage(slug) {
  const label = slug && slug !== 'todas' ? state.categories.find(x => x.toLowerCase() === decodeURIComponent(slug).toLowerCase()) || 'Novedades' : 'Todas las prendas';
  const list = state.products.filter(p => (label === 'Todas las prendas' || (label === 'Novedades' ? p.badge === 'Nuevo' : p.category === label)) && p.name.toLowerCase().includes((document.querySelector('#search')?.value || '').toLowerCase()));
  return `<section class="page-banner"><span class="eyebrow">COLECCIÓN DEMO / ${esc(label).toUpperCase()}</span><h1>${esc(label)}</h1><p>Ropa de muestra, pensada para mostrar la experiencia de compra y gestión.</p><div class="collection-filter">${state.categories.map(c => `<a class="filter-chip ${label===c?'selected':''}" href="#coleccion/${encodeURIComponent(c.toLowerCase())}">${esc(c)}</a>`).join('')}<a class="filter-chip ${label==='Todas las prendas'?'selected':''}" href="#coleccion/todas">Ver todo</a></div></section><section class="product-section collection-products"><div class="section-heading"><div><span class="eyebrow">${list.length} PRENDAS DE MUESTRA</span><h2>${esc(label)}</h2></div><label class="sort-control">Ordenar <select id="sort-products"><option value="featured">Destacados</option><option value="price-up">Precio: menor a mayor</option><option value="price-down">Precio: mayor a menor</option></select></label></div><div class="product-grid">${list.length ? list.map(productCard).join('') : '<p class="empty-state">No hay prendas en esta categoría todavía.</p>'}</div></section>`;
}

function productPage(id) {
  const p = state.products.find(item => item.id === Number(id));
  if (!p) return `<section class="page-banner"><h1>Prenda no encontrada</h1><a class="text-link" href="#coleccion/todas">Volver al catálogo</a></section>`;
  return `<section class="product-detail"><div class="detail-image">${p.badge ? `<span class="badge">${esc(p.badge)}</span>` : ''}${garment(p.type, p.color, 'detail-garment')}<span class="image-caption">[ TU MARCA ] / COLECCIÓN DEMO</span></div><div class="detail-copy"><span class="eyebrow">${esc(p.category).toUpperCase()} · PRENDA DE MUESTRA</span><h1>${esc(p.name)}</h1><div class="detail-price">${money(p.price)} ${p.oldPrice ? `<del>${money(p.oldPrice)}</del>` : ''}</div><p>Una prenda de ejemplo para recorrer las opciones reales de la tienda: selección de variante, disponibilidad, bolsa y compra simulada.</p><p class="stock-note ${p.stock?'':'out'}">${p.stock ? `${p.stock} unidades de muestra disponibles` : 'Sin existencias · ejemplo de producto agotado'}</p><form id="add-detail-form"><label>Talla<select name="size" required>${p.sizes.split(',').map(s => `<option>${esc(s.trim())}</option>`).join('')}</select></label><label>Color<select name="color" required>${p.colors.split(',').map(s => `<option>${esc(s.trim())}</option>`).join('')}</select></label><label>Cantidad<input name="qty" type="number" min="1" max="${Math.max(1,p.stock)}" value="1" ${p.stock ? '' : 'disabled'}></label><button class="button-primary" type="submit" ${p.stock ? '' : 'disabled'}>${p.stock ? 'Añadir a la bolsa' : 'Agotado'}</button></form><div class="detail-assurances"><span>✓ Compra de demostración</span><span>✓ Sin pago real</span><span>✓ Variantes de ejemplo</span></div><a href="#coleccion/${encodeURIComponent(p.category.toLowerCase())}" class="text-link">← Volver a ${esc(p.category)}</a></div></section>`;
}

function cartPage() {
  if (!state.cart.length) return `<section class="simple-page"><span class="eyebrow">TU SELECCIÓN</span><h1>La bolsa está vacía</h1><p>Descubre la colección y añade una prenda para probar el proceso.</p><a class="button-primary" href="#coleccion/todas">Ver prendas ↗</a></section>`;
  const subtotal = state.cart.reduce((sum, item) => sum + item.price * item.qty, 0);
  const selectedCoupon = state.coupons.find(c => c.code === state.coupon && c.active);
  const discount = selectedCoupon ? subtotal * selectedCoupon.discount / 100 : 0;
  return `<section class="cart-page"><div><span class="eyebrow">TU SELECCIÓN</span><h1>Bolsa de compra</h1>${state.cart.map(item => `<article class="cart-line"><div class="cart-art">${garment(item.type, item.colorHex)}</div><div class="cart-product"><a href="#producto/${item.id}">${esc(item.name)}</a><small>Talla ${esc(item.size)} · ${esc(item.color)}</small><small>${money(item.price)} / unidad</small></div><label class="quantity">Unidades <input data-qty="${item.key}" type="number" min="1" value="${item.qty}"></label><strong>${money(item.price * item.qty)}</strong><button class="remove-btn" data-remove="${item.key}" aria-label="Quitar ${esc(item.name)}">×</button></article>`).join('')}<a href="#coleccion/todas" class="text-link">← Seguir comprando</a></div><aside class="summary-card"><h2>Resumen</h2><div class="summary-row"><span>Subtotal</span><b>${money(subtotal)}</b></div>${discount ? `<div class="summary-row discount"><span>Cupón DEMO10</span><b>− ${money(discount)}</b></div>` : ''}<div class="summary-row"><span>Envío de demostración</span><b>Gratis</b></div><form id="coupon-form" class="coupon-form"><label for="coupon-code">Código promocional</label><div><input id="coupon-code" value="${esc(state.coupon)}" placeholder="DEMO10"><button type="submit">Aplicar</button></div><small>Prueba el cupón de muestra DEMO10.</small></form><div class="summary-total"><span>Total de demostración</span><b>${money(subtotal - discount)}</b></div><p class="demo-disclaimer">No se cobran pagos ni se envían productos.</p><button class="button-primary full-width" data-go="checkout">Continuar al checkout →</button></aside></section>`;
}

function accountPage() {
  const mine = state.orders.filter(o => o.email === state.customer.email || o.customer === state.customer.name);
  const tab = state.tab || 'orders';
  return `<section class="account-page"><header class="page-banner compact"><span class="eyebrow">ÁREA DE CLIENTE · DEMO</span><h1>Mi cuenta</h1><p>Pedidos, datos personales y direcciones.</p></header><div class="account-layout"><nav class="account-nav"><button data-tab="orders" class="${tab==='orders'?'active':''}">Mis pedidos</button><button data-tab="profile" class="${tab==='profile'?'active':''}">Datos personales</button><button data-tab="addresses" class="${tab==='addresses'?'active':''}">Direcciones</button><button data-action="logout">Cerrar sesión demo</button></nav><div class="account-content">${tab === 'orders' ? `<div class="panel-card"><div class="section-heading"><div><span class="eyebrow">HISTORIAL</span><h2>Hola, ${esc(state.customer.name.split(' ')[0])}</h2></div><button class="button-secondary" data-action="new-order">Crear pedido de ejemplo</button></div>${orderTable(mine, 'customer')}</div>` : tab === 'profile' ? `<div class="panel-card"><span class="eyebrow">TU PERFIL</span><h2>Datos personales</h2><form id="profile-form" class="form-grid"><label>Nombre y apellidos<input name="name" value="${esc(state.customer.name)}" required></label><label>Correo electrónico<input name="email" type="email" value="${esc(state.customer.email)}" required></label><label>Teléfono<input name="phone" value="${esc(state.customer.phone)}"></label><button class="button-primary" type="submit">Guardar cambios</button></form></div>` : `<div class="panel-card"><span class="eyebrow">TU PERFIL</span><h2>Dirección de envío</h2><form id="address-form" class="form-grid"><label>Dirección<input name="address" value="${esc(state.customer.address)}"></label><label>Ciudad<input name="city" value="${esc(state.customer.city)}"></label><label>Código postal<input name="postcode" value="${esc(state.customer.postcode)}"></label><button class="button-primary" type="submit">Guardar dirección</button></form></div>`}</div></div><p class="demo-disclaimer">Esta vista simula el área de cliente; no crea una cuenta real ni envía correos.</p></section>`;
}

function accountWelcome() {
  return `<section class="simple-page account-welcome"><span class="eyebrow">ACCESO A LA TIENDA</span><h1>Entra en tu cuenta</h1><p>En la tienda final, cada persona verá solo sus datos y pedidos. Aquí puedes abrir la vista cliente sin crear credenciales.</p><button class="button-primary" data-role="customer">Entrar como cliente demo ↗</button><div class="register-demo"><h2>Crear cuenta de muestra</h2><form id="register-form" class="form-grid"><label>Nombre<input name="name" required placeholder="Nombre Demo"></label><label>Correo de prueba<input name="email" type="email" required placeholder="prueba@example.test"></label><button class="button-secondary" type="submit">Crear perfil ficticio</button></form></div></section>`;
}

function orderTable(rows, context = 'admin') {
  if (!rows.length) return '<div class="empty-state">Todavía no hay pedidos en esta vista.</div>';
  return `<div class="table-scroll"><table><thead><tr><th>Pedido</th>${context !== 'customer' ? '<th>Cliente</th>' : ''}<th>Fecha</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.map(order => `<tr><td><b>${esc(order.id)}</b><small>${order.items.map(item => `${esc(item.name)} × ${item.qty}`).join('<br>')}</small></td>${context !== 'customer' ? `<td>${esc(order.customer)}</td>` : ''}<td>${esc(order.date)}</td><td>${money(order.total)}</td><td><span class="status ${order.status==='Completado'?'done':order.status==='Cancelado'?'cancel':'pending'}">${esc(order.status)}</span></td><td><button class="small-action" data-order="${esc(order.id)}">Ver pedido</button>${context === 'customer' && ['Pendiente de pago', 'Fallido', 'En espera'].includes(order.status) ? `<button class="small-action danger" data-cancel="${esc(order.id)}">Cancelar</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`;
}

function adminPage() {
  const items = [['resumen', 'Resumen'], ['productos', 'Productos'], ['categorias', 'Categorías'], ['pedidos', 'Pedidos'], ['promociones', 'Promociones'], ['cuentas', 'Cuentas'], ['pagos', 'Pagos'], ['envios', 'Envíos'], ['personalizacion', 'Personalización'], ['perfil', 'Perfil']];
  return `<section class="admin-page"><header class="admin-heading"><div><span class="eyebrow">ESPACIO DE GESTIÓN · DEMO</span><h1>Panel de administración</h1></div><span class="role-badge">Administrador</span></header><div class="admin-layout"><nav class="admin-nav">${items.map(([id, label]) => `<button data-tab="${id}" class="${state.tab===id?'active':''}">${label}</button>`).join('')}<button data-role="shopper" class="back-shop">↗ Ver tienda</button></nav><div class="admin-content">${adminContent()}</div></div><p class="demo-disclaimer">Solo cambias datos ficticios guardados en este navegador; no es el panel real del cliente.</p></section>`;
}

function employeePage() {
  const items = [['resumen', 'Resumen'], ['productos', 'Productos'], ['pedidos', 'Pedidos']];
  return `<section class="admin-page"><header class="admin-heading"><div><span class="eyebrow">ESPACIO DE GESTIÓN · DEMO</span><h1>Panel de equipo</h1></div><span class="role-badge employee-badge">Empleado</span></header><div class="admin-layout"><nav class="admin-nav">${items.map(([id, label]) => `<button data-tab="${id}" class="${state.tab===id?'active':''}">${label}</button>`).join('')}<button data-role="shopper" class="back-shop">↗ Ver tienda</button></nav><div class="admin-content">${state.tab === 'productos' ? productsAdmin(true) : state.tab === 'pedidos' ? `<section class="panel-card"><span class="eyebrow">PREPARACIÓN</span><h2>Consulta de pedidos</h2><p>El empleado puede revisar artículos, estado y dirección de preparación. No modifica estados ni accede a pagos o cuentas.</p>${orderTable(state.orders, 'employee')}</section>` : dashboard(true)}</div></div><p class="demo-disclaimer">Vista ilustrativa de permisos. La demo no crea usuarios ni sesiones reales.</p></section>`;
}

function dashboard(employee = false) {
  const gross = state.orders.filter(order => order.status !== 'Cancelado').reduce((sum, order) => sum + order.total, 0);
  const outstanding = state.orders.filter(order => ['Pendiente de pago', 'En preparación', 'En espera'].includes(order.status)).length;
  const out = state.products.filter(p => p.stock === 0).length;
  return `<div class="metric-grid"><div class="metric-card"><span>PEDIDOS DE MUESTRA</span><b>${state.orders.length}</b><small>Actividad del prototipo</small></div><div class="metric-card"><span>VENTAS DE MUESTRA</span><b>${money(gross)}</b><small>Sin transacciones reales</small></div><div class="metric-card"><span>POR ATENDER</span><b>${outstanding}</b><small>Pedidos no finalizados</small></div><div class="metric-card"><span>AGOTADOS</span><b>${out}</b><small>Productos sin stock</small></div></div><section class="panel-card"><div class="section-heading"><div><span class="eyebrow">ACTIVIDAD RECIENTE</span><h2>Últimos pedidos</h2></div><button class="text-link" data-tab="pedidos">Ver pedidos ↗</button></div>${orderTable(state.orders.slice(0, 3), employee ? 'employee' : 'admin')}</section>${employee ? '<section class="panel-card"><h2>Tu acceso</h2><p>Puede editar productos y consultar los pedidos para preparar. Las cuentas, pagos y ajustes quedan reservados al administrador.</p></section>' : '<section class="panel-card"><h2>Gestión básica de tienda</h2><p>Productos, colecciones, pedidos, cuentas y ajustes clave. Las herramientas técnicas de WordPress quedan fuera de esta vista de negocio.</p></section>'}`;
}

function productsAdmin(employee = false) {
  return `<section class="panel-card"><div class="section-heading"><div><span class="eyebrow">CATÁLOGO Y EXISTENCIAS</span><h2>Productos</h2></div><button class="button-primary compact-button" data-action="new-product">+ Añadir producto</button></div><div class="table-scroll"><table><thead><tr><th>Prenda</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Acciones</th></tr></thead><tbody>${state.products.map(product => `<tr><td><b>${esc(product.name)}</b><small>Tallas: ${esc(product.sizes)}</small></td><td>${esc(product.category)}</td><td>${money(product.price)}</td><td><span class="status ${product.stock?'done':'cancel'}">${product.stock ? `${product.stock} uds.` : 'Agotado'}</span></td><td><button class="small-action" data-edit-product="${product.id}">Editar</button>${employee ? '' : `<button class="small-action danger" data-delete-product="${product.id}">Eliminar</button>`}</td></tr>`).join('')}</tbody></table></div><p class="help-note">Puedes actualizar nombre, categoría, precio, stock, tallas, colores e imagen ilustrativa. Los cambios aparecen en la tienda.</p></section>`;
}

function categoriesAdmin() {
  return `<section class="panel-card"><div class="section-heading"><div><span class="eyebrow">NAVEGACIÓN DE LA TIENDA</span><h2>Categorías</h2></div><button class="button-primary compact-button" data-action="new-category">+ Nueva categoría</button></div><div class="category-admin-list">${state.categories.map((category, index) => `<div class="category-admin-row"><span class="category-index">0${index + 1}</span><b>${esc(category)}</b><span>${state.products.filter(p => p.category === category).length} prendas de muestra</span><button class="small-action" data-edit-category="${index}">Renombrar</button><button class="small-action danger" data-delete-category="${index}">Eliminar</button></div>`).join('')}</div><p class="help-note">Las categorías se reflejan en los enlaces de colección y en el catálogo.</p></section>`;
}

function promotionsAdmin() {
  return `<section class="panel-card"><div class="section-heading"><div><span class="eyebrow">CÓDIGOS DE DESCUENTO</span><h2>Promociones</h2></div><button class="button-primary compact-button" data-action="new-coupon">+ Crear promoción</button></div><div class="table-scroll"><table><thead><tr><th>Código</th><th>Descuento</th><th>Caducidad</th><th>Usos</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.coupons.map((coupon, index) => `<tr><td><b>${esc(coupon.code)}</b></td><td>${coupon.discount}%</td><td>${esc(coupon.expires || 'Sin caducidad')}</td><td>${coupon.uses || 0} / ${coupon.maxUses || '∞'}</td><td><span class="status ${coupon.active?'done':'cancel'}">${coupon.active ? 'Activa' : 'Pausada'}</span></td><td><button class="small-action" data-edit-coupon="${index}">Editar</button><button class="small-action danger" data-delete-coupon="${index}">Eliminar</button></td></tr>`).join('')}</tbody></table></div><p class="help-note">El código DEMO10 puede aplicarse en la bolsa; los descuentos solo alteran el total ficticio.</p></section>`;
}

function accountsAdmin() {
  return `<section class="panel-card"><div class="section-heading"><div><span class="eyebrow">PERSONAS Y NIVELES DE ACCESO</span><h2>Cuentas de ejemplo</h2></div><button class="button-primary compact-button" data-action="new-user">+ Crear cuenta</button></div><div class="table-scroll"><table><thead><tr><th>Nombre</th><th>Correo de muestra</th><th>Nivel</th><th>Alta</th><th>Acciones</th></tr></thead><tbody>${state.users.map((user, i) => `<tr><td><b>${esc(user.name)}</b></td><td>${esc(user.email)}</td><td><span class="role-badge small-role ${user.role.toLowerCase()}">${esc(user.role)}</span></td><td>${esc(user.since)}</td><td><button class="small-action" data-edit-user="${i}">Editar</button><button class="small-action danger" data-delete-user="${i}">Eliminar</button></td></tr>`).join('')}</tbody></table></div><div class="roles-explainer"><b>Administrador</b><span>Gestiona la tienda y sus cuentas.</span><b>Empleado</b><span>Edita productos y consulta pedidos.</span><b>Cliente</b><span>Accede a sus datos personales y pedidos.</span></div><p class="help-note">No se crean usuarios ni contraseñas reales en esta demostración.</p></section>`;
}

function adminContent() {
  if (state.tab === 'productos') return productsAdmin();
  if (state.tab === 'categorias') return categoriesAdmin();
  if (state.tab === 'pedidos') return `<section class="panel-card"><span class="eyebrow">OPERACIÓN DE TIENDA</span><h2>Pedidos</h2><p>Consulta los artículos y actualiza el estado de cada pedido ficticio.</p>${orderTable(state.orders)}</section>`;
  if (state.tab === 'promociones') return promotionsAdmin();
  if (state.tab === 'cuentas') return accountsAdmin();
  if (state.tab === 'pagos') return `<section class="panel-card"><span class="eyebrow">AJUSTES DE COMPRA</span><h2>Pagos</h2><div class="setting-row"><div><b>Pago de prueba (demo)</b><small>Método ficticio activo para mostrar el checkout.</small></div><span class="status done">Demo activo</span></div><div class="setting-row"><div><b>Pasarelas reales</b><small>Se conectan con las credenciales del negocio al preparar el sitio final.</small></div><span class="status">Sin conectar</span></div><p class="demo-disclaimer">No introduzcas datos bancarios aquí. Esta maqueta no procesa transacciones.</p></section>`;
  if (state.tab === 'envios') return `<section class="panel-card"><span class="eyebrow">ENTREGA</span><h2>Envíos</h2><div class="setting-row"><div><b>Envío gratuito (demo)</b><small>Opción visible durante el checkout de muestra.</small></div><span class="status done">Disponible</span></div><div class="setting-row"><div><b>Dirección de entrega</b><small>Se solicita como dato ficticio al finalizar la compra.</small></div><span class="status">Demo</span></div></section>`;
  if (state.tab === 'personalizacion') return `<section class="panel-card"><span class="eyebrow">APARIENCIA Y CONTENIDO</span><h2>Personalización</h2><p>El nombre, el logo, el favicon, las campañas por diseño, las imágenes de colecciones y los datos de contacto se preparan aquí en el sitio real.</p><div class="setting-row"><div><b>Diseños públicos</b><small>Editorial · Mediterránea · Street · Premium</small></div><button class="small-action" data-role="shopper">Probar diseños</button></div><div class="setting-row"><div><b>Identidad de la demo</b><small>Nombre neutral “Tu marca”; no contiene la marca ni el logo del cliente.</small></div><span class="status">Editable en la tienda final</span></div></section>`;
  if (state.tab === 'perfil') return `<section class="panel-card"><span class="eyebrow">CUENTA DEL NEGOCIO</span><h2>Perfil</h2><form id="store-profile-form" class="form-grid"><label>Nombre de contacto<input name="contact" value="${esc(state.profile.contact)}"></label><label>Correo de muestra<input name="email" type="email" value="${esc(state.profile.email)}"></label><label>Teléfono ficticio<input name="phone" value="${esc(state.profile.phone)}"></label><button class="button-primary">Guardar perfil de muestra</button></form></section>`;
  return dashboard();
}

function pageFromHash() {
  const parts = decodeURIComponent(location.hash.replace(/^#/, '')).split('/');
  state.page = parts[0] || 'tienda';
  return parts;
}

function render() {
  const [page, param] = pageFromHash();
  document.body.dataset.theme = state.theme;
  roleSelect.value = state.role;
  document.querySelector('#cart-count').textContent = cartQty();
  document.querySelectorAll('[data-theme]').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.theme === state.theme)));
  if (state.role === 'admin') app.innerHTML = adminPage();
  else if (state.role === 'employee') app.innerHTML = employeePage();
  else if (page === 'cuenta' && state.role === 'customer') app.innerHTML = accountPage();
  else if (page === 'cuenta') app.innerHTML = accountWelcome();
  else if (page === 'carrito') app.innerHTML = cartPage();
  else if (page === 'checkout') app.innerHTML = checkoutPage();
  else if (page === 'producto') app.innerHTML = productPage(param);
  else if (page === 'coleccion') app.innerHTML = collectionPage(param);
  else app.innerHTML = homePage();
  if (page === 'coleccion') {
    const sort = document.querySelector('#sort-products');
    sort?.addEventListener('change', () => { const cards = [...app.querySelectorAll('.product-card')]; if (sort.value !== 'featured') { const order = sort.value === 'price-up' ? 1 : -1; cards.sort((a,b) => order * (Number(a.querySelector('.product-meta strong').textContent.replace(/[^\d,]/g,'').replace(',','.')) - Number(b.querySelector('.product-meta strong').textContent.replace(/[^\d,]/g,'').replace(',','.')))); cards.forEach(card => card.parentElement.appendChild(card)); } });
  }
  persist();
}

function checkoutPage() {
  if (!state.cart.length) return `<section class="simple-page"><h1>No hay artículos en la bolsa</h1><a class="button-primary" href="#coleccion/todas">Volver al catálogo</a></section>`;
  const subtotal = state.cart.reduce((sum, item) => sum + item.price * item.qty, 0);
  const selectedCoupon = state.coupons.find(c => c.code === state.coupon && c.active);
  const total = subtotal - (selectedCoupon ? subtotal * selectedCoupon.discount / 100 : 0);
  return `<section class="checkout-page"><div><span class="eyebrow">ÚLTIMO PASO · DEMO</span><h1>Finalizar pedido</h1><p>Usa datos ficticios. No se necesita tarjeta y no se envía correo.</p><form id="checkout-form"><div class="checkout-block"><h2>Datos de entrega</h2><div class="form-grid"><label>Nombre<input name="name" value="${esc(state.customer.name)}" required></label><label>Correo electrónico<input name="email" type="email" value="${esc(state.customer.email)}" required></label><label>Dirección<input name="address" value="${esc(state.customer.address)}" required></label><label>Ciudad<input name="city" value="${esc(state.customer.city)}" required></label><label>Código postal<input name="postcode" value="${esc(state.customer.postcode)}" required></label></div></div><div class="checkout-block"><h2>Envío</h2><label class="radio-row"><input type="radio" checked disabled> Envío gratuito de demostración <b>Gratis</b></label></div><div class="checkout-block"><h2>Pago</h2><label class="radio-row"><input type="radio" checked disabled> Pago de prueba (demo) <b>Sin cargo</b></label><p class="help-note">Este prototipo no acepta ni solicita datos bancarios.</p></div><button class="button-primary" type="submit">Realizar pedido de muestra · ${money(total)}</button></form></div><aside class="summary-card"><h2>Tu pedido</h2>${state.cart.map(item => `<div class="summary-row"><span>${esc(item.name)} × ${item.qty}<small>Talla ${esc(item.size)} · ${esc(item.color)}</small></span><b>${money(item.qty * item.price)}</b></div>`).join('')}<div class="summary-row"><span>Envío</span><b>Gratis</b></div>${state.coupon === 'DEMO10' ? '<div class="summary-row discount"><span>DEMO10</span><b>−10 %</b></div>' : ''}<div class="summary-total"><span>Total</span><b>${money(total)}</b></div></aside></section>`;
}

function openDialog(title, body) { dialog.innerHTML = `<header class="dialog-head"><h2>${title}</h2><button type="button" data-close aria-label="Cerrar">×</button></header>${body}`; dialog.showModal(); }
function productForm(product = {}) {
  const creating = !product.id;
  openDialog(creating ? 'Añadir prenda de muestra' : 'Editar prenda', `<form id="product-form" class="form-grid"><input type="hidden" name="id" value="${product.id||''}"><label>Nombre<input name="name" value="${esc(product.name||'')}" required></label><label>Categoría<select name="category">${state.categories.map(c => `<option ${product.category === c ? 'selected' : ''}>${esc(c)}</option>`).join('')}</select></label><label>Precio (€)<input name="price" type="number" step="0.01" min="0" value="${product.price??''}" required></label><label>Stock<input name="stock" type="number" min="0" value="${product.stock??1}" required></label><label>Tallas<input name="sizes" value="${esc(product.sizes||'XS, S, M, L, XL')}"></label><label>Colores<input name="colors" value="${esc(product.colors||'Arena, Negro')}"></label><label>Color de ilustración<input name="color" type="color" value="${esc(product.color||'#b9a894')}"></label><label>Tipo de prenda<select name="type">${['shirt','sweatshirt','dress','pants','sweater'].map(t => `<option ${product.type === t ? 'selected' : ''}>${t}</option>`).join('')}</select></label><div class="dialog-actions"><button class="button-secondary" type="button" data-close>Cancelar</button><button class="button-primary" type="submit">Guardar en la demo</button></div></form>`);
}
function userForm(user = {}, index = '') {
  openDialog(index === '' ? 'Crear cuenta ficticia' : 'Editar cuenta ficticia', `<form id="user-form" class="form-grid"><input type="hidden" name="index" value="${index}"><label>Nombre<input name="name" value="${esc(user.name||'')}" required></label><label>Correo de muestra<input name="email" type="email" value="${esc(user.email||'')}" required></label><label>Nivel<select name="role">${['Administrador','Empleado','Cliente'].map(role => `<option ${user.role === role ? 'selected' : ''}>${role}</option>`).join('')}</select></label><p class="help-note">No se crean credenciales ni cuentas reales.</p><div class="dialog-actions"><button class="button-secondary" type="button" data-close>Cancelar</button><button class="button-primary" type="submit">Guardar</button></div></form>`);
}
function couponForm(coupon = {}, index = '') { openDialog(index === '' ? 'Crear promoción ficticia' : 'Editar promoción', `<form id="coupon-form-admin" class="form-grid"><input type="hidden" name="index" value="${index}"><label>Código<input name="code" value="${esc(coupon.code||'')}" required></label><label>Descuento (%)<input name="discount" type="number" min="1" max="90" value="${coupon.discount||10}" required></label><label>Caducidad<input name="expires" value="${esc(coupon.expires||'')}" placeholder="31 dic 2026"></label><label>Límite de usos<input name="maxUses" type="number" min="1" value="${coupon.maxUses||100}"></label><label><span>Estado</span><select name="active"><option value="true" ${coupon.active !== false ? 'selected' : ''}>Activa</option><option value="false" ${coupon.active === false ? 'selected' : ''}>Pausada</option></select></label><div class="dialog-actions"><button class="button-secondary" type="button" data-close>Cancelar</button><button class="button-primary">Guardar promoción</button></div></form>`); }
function categoryForm(value = '', index = '') { openDialog(index === '' ? 'Nueva categoría' : 'Renombrar categoría', `<form id="category-form"><label>Nombre de colección<input name="name" value="${esc(value)}" required></label><input type="hidden" name="index" value="${index}"><div class="dialog-actions"><button type="button" class="button-secondary" data-close>Cancelar</button><button class="button-primary">Guardar</button></div></form>`); }

document.addEventListener('click', event => {
  const target = event.target.closest('button, a');
  if (!target) return;
  if (target.dataset.theme) { state.theme = target.dataset.theme; persist(); render(); toast(`Diseño ${target.textContent.trim()} aplicado`); }
  else if (target.dataset.page === 'cuenta') { location.hash = '#cuenta'; }
  else if (target.dataset.page === 'carrito') { location.hash = '#carrito'; }
  else if (target.dataset.add) {
    const p = state.products.find(item => item.id === Number(target.dataset.add));
    if (p && p.stock > 0) { const line = state.cart.find(item => item.id === p.id && item.size === p.sizes.split(',')[0].trim()); if (line) line.qty++; else state.cart.push({ key: `${p.id}-M-${Date.now()}`, id: p.id, name: p.name, size: p.sizes.split(',')[0].trim(), color: p.colors.split(',')[0].trim(), colorHex: p.color, price: p.price, qty: 1, type: p.type }); persist(); render(); toast('Prenda añadida a la bolsa de muestra'); }
  }
  else if (target.dataset.tab) { state.tab = target.dataset.tab; persist(); render(); }
  else if (target.dataset.role) { state.role = target.dataset.role; state.tab = target.dataset.role === 'admin' || target.dataset.role === 'employee' ? 'resumen' : 'orders'; location.hash = target.dataset.role === 'customer' ? '#cuenta' : '#tienda'; persist(); render(); }
  else if (target.dataset.go === 'checkout') location.hash = '#checkout';
  else if (target.dataset.action === 'logout') { state.role = 'shopper'; location.hash = '#tienda'; render(); toast('Has salido de la vista de cliente demo'); }
  else if (target.dataset.action === 'new-order') { state.role = 'shopper'; location.hash = '#coleccion/todas'; toast('Añade una prenda y completa el checkout demo para crear un pedido.'); }
  else if (target.dataset.action === 'new-product') productForm();
  else if (target.dataset.action === 'new-user') userForm();
  else if (target.dataset.action === 'new-category') categoryForm();
  else if (target.dataset.action === 'new-coupon') couponForm();
  else if (target.dataset.editProduct) productForm(state.products.find(p => p.id === Number(target.dataset.editProduct)));
  else if (target.dataset.deleteProduct && confirm('¿Retirar esta prenda ficticia del catálogo?')) { state.products = state.products.filter(p => p.id !== Number(target.dataset.deleteProduct)); persist(); render(); toast('Prenda retirada de la demo'); }
  else if (target.dataset.editUser !== undefined) userForm(state.users[Number(target.dataset.editUser)], target.dataset.editUser);
  else if (target.dataset.deleteUser !== undefined && confirm('¿Eliminar esta cuenta ficticia de la demo?')) { state.users.splice(Number(target.dataset.deleteUser), 1); persist(); render(); toast('Cuenta ficticia eliminada'); }
  else if (target.dataset.editCategory !== undefined) categoryForm(state.categories[Number(target.dataset.editCategory)], target.dataset.editCategory);
  else if (target.dataset.deleteCategory !== undefined && confirm('¿Eliminar esta categoría ficticia?')) { const name = state.categories[Number(target.dataset.deleteCategory)]; state.categories.splice(Number(target.dataset.deleteCategory), 1); state.products = state.products.filter(p => p.category !== name); persist(); render(); toast('Categoría eliminada de la demo'); }
  else if (target.dataset.editCoupon !== undefined) couponForm(state.coupons[Number(target.dataset.editCoupon)], target.dataset.editCoupon);
  else if (target.dataset.deleteCoupon !== undefined && confirm('¿Eliminar esta promoción ficticia?')) { state.coupons.splice(Number(target.dataset.deleteCoupon), 1); if (!state.coupons.some(c => c.code === state.coupon)) state.coupon = ''; persist(); render(); toast('Promoción eliminada de la demo'); }
  else if (target.dataset.remove) { state.cart = state.cart.filter(item => item.key !== target.dataset.remove); persist(); render(); }
  else if (target.dataset.order) {
    const order = state.orders.find(item => item.id === target.dataset.order);
    openDialog(`Pedido ${esc(order.id)}`, `<p><b>${esc(order.customer)}</b> · ${esc(order.email)}</p><p>${esc(order.date)} · ${money(order.total)}</p><ul>${order.items.map(item => `<li>${esc(item.name)} — talla ${esc(item.size)}, color ${esc(item.color)} × ${item.qty}</li>`).join('')}</ul><p>Estado actual: <span class="status pending">${esc(order.status)}</span></p>${state.role === 'admin' ? `<form id="order-status-form"><label>Actualizar estado<select name="status">${['Pendiente de pago','En espera','En preparación','Completado','Cancelado','Fallido'].map(status => `<option ${status === order.status ? 'selected' : ''}>${status}</option>`).join('')}</select></label><input name="id" type="hidden" value="${esc(order.id)}"><button class="button-primary">Guardar estado de muestra</button></form>` : '<p class="help-note">El empleado solo consulta este pedido; el comprador puede cancelar pedidos pendientes.</p>'}`);
  }
  else if (target.dataset.cancel && confirm('¿Cancelar este pedido de demostración? No se realiza ningún reembolso real.')) { const order = state.orders.find(item => item.id === target.dataset.cancel); if (order) order.status = 'Cancelado'; persist(); render(); toast('Pedido cancelado en la demo'); }
  else if (target.hasAttribute('data-close')) dialog.close();
});

document.addEventListener('change', event => {
  const target = event.target;
  if (target.id === 'role-select') { state.role = target.value; state.tab = target.value === 'admin' || target.value === 'employee' ? 'resumen' : 'orders'; location.hash = target.value === 'customer' ? '#cuenta' : '#tienda'; persist(); render(); }
  if (target.dataset.qty) { const item = state.cart.find(line => line.key === target.dataset.qty); if (item) item.qty = Math.max(1, Number(target.value) || 1); persist(); render(); }
});

document.addEventListener('submit', event => {
  const form = event.target;
  if (form.id === 'add-detail-form') { event.preventDefault(); const [page, id] = pageFromHash(); const p = state.products.find(item => item.id === Number(id)); const data = new FormData(form); if (p?.stock) { state.cart.push({ key: `${p.id}-${Date.now()}`, id: p.id, name: p.name, size: data.get('size'), color: data.get('color'), colorHex: p.color, price: p.price, qty: Number(data.get('qty')) || 1, type: p.type }); persist(); location.hash = '#carrito'; toast('Prenda añadida a la bolsa de muestra'); } }
  if (form.id === 'coupon-form') { event.preventDefault(); const code = document.querySelector('#coupon-code').value.trim().toUpperCase(); const coupon = state.coupons.find(c => c.code === code && c.active && (!c.maxUses || c.uses < c.maxUses)); if (coupon) { state.coupon = code; persist(); render(); toast(`Cupón ${code} aplicado`); } else toast('Ese código no está disponible en esta demo'); }
  if (form.id === 'profile-form') { event.preventDefault(); Object.assign(state.customer, Object.fromEntries(new FormData(form))); persist(); render(); toast('Datos ficticios guardados en este navegador'); }
  if (form.id === 'address-form') { event.preventDefault(); Object.assign(state.customer, Object.fromEntries(new FormData(form))); persist(); render(); toast('Dirección ficticia guardada'); }
  if (form.id === 'register-form') { event.preventDefault(); const data = Object.fromEntries(new FormData(form)); state.customer.name = data.name; state.customer.email = data.email; state.users.push({ ...data, role: 'Cliente', since: 'Hoy' }); state.role = 'customer'; state.tab = 'orders'; persist(); location.hash = '#cuenta'; render(); toast('Perfil ficticio creado; no se envió correo'); }
  if (form.id === 'product-form') { event.preventDefault(); const data = Object.fromEntries(new FormData(form)); data.id = data.id ? Number(data.id) : Date.now(); data.price = Number(data.price); data.stock = Number(data.stock); const existing = state.products.find(p => p.id === data.id); if (existing) Object.assign(existing, data); else state.products.unshift(data); persist(); dialog.close(); render(); toast('Catálogo de muestra actualizado'); }
  if (form.id === 'user-form') { event.preventDefault(); const data = Object.fromEntries(new FormData(form)); if (data.index === '') state.users.push({ ...data, since: 'Hoy' }); else state.users[Number(data.index)] = { ...state.users[Number(data.index)], ...data }; persist(); dialog.close(); render(); toast('Cuenta ficticia actualizada'); }
  if (form.id === 'coupon-form-admin') { event.preventDefault(); const data = Object.fromEntries(new FormData(form)); data.code = data.code.trim().toUpperCase(); data.discount = Number(data.discount); data.maxUses = Number(data.maxUses) || 0; data.active = data.active === 'true'; data.uses = data.index === '' ? 0 : state.coupons[Number(data.index)].uses || 0; if (data.index === '') state.coupons.push(data); else state.coupons[Number(data.index)] = data; persist(); dialog.close(); render(); toast('Promoción ficticia actualizada'); }
  if (form.id === 'category-form') { event.preventDefault(); const data = new FormData(form); const name = data.get('name').trim(); const index = data.get('index'); if (index === '') state.categories.push(name); else { const old = state.categories[Number(index)]; state.categories[Number(index)] = name; state.products.filter(p => p.category === old).forEach(p => p.category = name); } persist(); dialog.close(); render(); toast('Categorías de muestra actualizadas'); }
  if (form.id === 'store-profile-form') { event.preventDefault(); Object.assign(state.profile, Object.fromEntries(new FormData(form))); persist(); render(); toast('Perfil ficticio guardado'); }
  if (form.id === 'order-status-form') { event.preventDefault(); const data = new FormData(form); const order = state.orders.find(item => item.id === data.get('id')); if (order) order.status = data.get('status'); persist(); dialog.close(); render(); toast('Estado de pedido actualizado en la demo'); }
  if (form.id === 'checkout-form') { event.preventDefault(); const data = Object.fromEntries(new FormData(form)); Object.assign(state.customer, data); const subtotal = state.cart.reduce((sum, item) => sum + item.price * item.qty, 0); const coupon = state.coupons.find(c => c.code === state.coupon && c.active); const total = subtotal - (coupon ? subtotal * coupon.discount / 100 : 0); if (coupon) coupon.uses = (coupon.uses || 0) + 1; const next = 130 + state.orders.length; state.orders.unshift({ id: `DEMO-${next}`, customer: state.customer.name, email: state.customer.email, date: new Intl.DateTimeFormat('es-ES', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date()), total, status: 'En preparación', items: clone(state.cart) }); state.cart = []; state.coupon = ''; state.role = 'customer'; state.tab = 'orders'; persist(); location.hash = '#cuenta'; render(); toast(`Pedido DEMO-${next} creado · sin cobro real`); }
});

document.querySelector('#reset-demo').addEventListener('click', () => { if (confirm('¿Restaurar el catálogo, las cuentas y los pedidos iniciales ficticios de esta demo?')) { state = clone(seed); persist(); location.hash = '#tienda'; render(); toast('Demo restaurada'); } });
document.querySelector('#search').addEventListener('keydown', event => { if (event.key === 'Enter') { event.preventDefault(); location.hash = '#coleccion/todas'; render(); } });
document.querySelector('#menu-toggle').addEventListener('click', () => document.querySelector('.main-nav').classList.toggle('open'));
window.addEventListener('hashchange', render);
render();